import type { CalculatorSeoData } from './types';
// ---------------------------------------------------------------------------
// Sales Forecast Calculator (suite) — Phase 17: stage-weighted pipeline with
// win rate, coverage and gap; revenue growth with a compounding projection;
// customer retention and churn. Figures are generated by the functions the
// tabs run.
